insert into config (key, value, description, needs_founder_signoff, server_only) values
  ('SCOPE_THRESHOLD', '0.8'::jsonb, 'Agent in/out-of-scope confidence needed to qualify or auto-decline. Tune against the eval set and the review approval rate.', false, false),
  ('BUDGET_REJECT_RATIO', '0.7'::jsonb, 'Confirmed budget below this × floor is a budget fail. Do not set to 0.20: T10 (₹1.5L vs ₹7L floor) must still be rejected.', false, false),
  ('ASK_BUDGET', 'true'::jsonb, 'Owner''s decision (2026-10-08): always ask for a ballpark budget. A refusal is accepted and never pushed.', false, false),
  ('COMMERCIAL_MIN_SQFT', '500'::jsonb, 'Smallest commercial project. Unconfirmed by the founder.', true, false),
  ('COMMERCIAL_MIN_SQFT_MODE', '"review"'::jsonb, '''review'' = below-minimum commercial goes to designer review; ''decline'' = hard decline. Switch to ''decline'' once the founder confirms COMMERCIAL_MIN_SQFT (and relabel eval T18).', true, false),
  ('COMMERCIAL_MAX_SQFT', '3000'::jsonb, 'Largest commercial project (services.md: up to ~3,000 sq ft).', false, false),
  ('MIN_LEAD_WEEKS', '6'::jsonb, 'Project must not need to be complete in under this many weeks from the call (services.md).', false, false),
  ('SITE_AVAILABLE_MAX_WEEKS', '10'::jsonb, 'Site must be available for execution within this many weeks (qualified.md criterion 3). Later availability → review, not decline.', false, false),
  ('BUDGET_FLOOR', '{"residential_per_sqft_inr":1800,"per_room_inr":350000,"commercial_per_sqft_inr":1200}'::jsonb, 'Internal budget floor derived from seed/pricing.md (lowest band). Never spoken, never sent to the voice agent.', false, true),
  ('OFFICE_HOURS', '{"timezone":"Asia/Kolkata","days":[1,2,3,4,5,6],"open":"10:00","close":"19:00"}'::jsonb, 'Front-desk hours (ISO weekdays, 1 = Monday). Used for after-hours flag and redirect transfers.', false, false),
  ('CALL_LIMITS', '{"target_s":180,"soft_wrap_s":255,"hard_max_s":300}'::jsonb, 'Call duration targets. At soft_wrap_s the agent moves to wrap-up.', false, false),
  ('DROP_RECOVERY', '{"callback_within_s":120,"max_attempts":1}'::jsonb, 'If a caller drops mid-call, place one outbound callback within this window.', false, false),
  ('APPROVAL_CALLBACK', '{"max_attempts":3,"slots_to_offer":3}'::jsonb, 'After a review lead is approved: outbound call attempts before falling back to an SMS booking link.', false, false),
  ('VOICE_SPEND_CAP', '{"cap_inr":20,"reserve_inr":0,"max_call_s":240,"outbound_attempts":1}'::jsonb, 'Hard cap on total Vaani spend: ₹20. Vaani bills per second (≈ ₹4.50/min observed 2026-10-09: 74.7 s = ₹5.60). No call is answered or placed once logged spend reaches the cap. VOICE_PROVIDER=simulated by default, so no credit is used unless explicitly switched.', false, false),
  ('COMPLAINT_CALLBACK_MINUTES', '15'::jsonb, 'No longer promised to callers (2026-10-08: never guarantee a time — say ''as soon as possible'' and ask when they''re free). Used only as the internal target for seniors.', false, false),
  ('INSIGHTS_REFRESH_DAILY_LIMIT', '3'::jsonb, 'On-demand Gemini insights refreshes allowed per day.', false, false),
  ('PROMPT_VERSION', '"v0"'::jsonb, 'Voice agent prompt version (stored on each call).', false, false),
  ('SMS_PROVIDER', '"console"'::jsonb, '''console'' logs SMS instead of sending (zero-cost mode, no DLT registration). ''msg91'' once DLT templates are approved.', false, false),
  ('PRICE_DEFLECTION_LINE', '"Pricing depends on the site, the materials you choose, and the scope — your designer will walk you through it in detail at the consultation. I can book that for you right now if you''d like."'::jsonb, 'The only permitted response to a pricing question (pricing.md).', false, false),
  ('DECLINE_LINE', '"This sounds like it may not be the right fit for us right now — but feel free to reach out if your timeline or scope changes."'::jsonb, 'Graceful close from qualified.md.', false, false),
  ('SMS_TEMPLATES', '{"booking_confirmation":{"dlt_template_id":null,"text":"Aangan Studio: your design consultation is booked for {#var#}. Your designer will call you before the meeting. To reschedule, reply or call {#var#}."},"booking_link":{"dlt_template_id":null,"text":"Aangan Studio: we tried calling to book your consultation. Pick a time that suits you here: {#var#}"},"review_reject":{"dlt_template_id":null,"text":"Aangan Studio: thank you for calling us. After reviewing your project, we''re not the right fit right now — feel free to reach out if your timeline or scope changes."},"complaint_ack":{"dlt_template_id":null,"text":"Aangan Studio: we''re sorry about this. A senior member of our team will call you back as soon as possible."}}'::jsonb, 'Customer SMS. Text is frozen once registered on DLT; URLs must be on a whitelisted domain.', true, false),
  ('ANSWER_MODE', '{"mode":"overflow","forward_after_rings":4}'::jsonb, '''overflow'' = the office line forwards to the AI number only when staff are busy / don''t answer (conditional call forwarding) and always after hours — the AI only handles calls staff can''t, which keeps voice cost down. ''always'' = the AI answers every call. Set on the phone line, not in code; this records the intent and labels calls.', false, false),
  ('INSUFFICIENT_INFO', '{"min_missing_core":3,"core_fields":["what_work","locality","deadline","budget","decision_maker"]}'::jsonb, 'If at least this many core intake fields are still missing (not asked, not answered) and nothing was booked, the lead becomes ''Callback needed'' for the helpdesk instead of a decision.', false, false),
  ('DEAL_HEALTH_BANDS', '{"high":70,"medium":45}'::jsonb, 'Deal health score thresholds (0–100). Uncalibrated until enough Won/Lost outcomes come back from HubSpot — compare with the win rate by band on the dashboard.', false, false),
  ('SHARE_TYPICAL_BUDGET', 'true'::jsonb, 'Owner''s decision (2026-10-08): ask for a ballpark budget; if none is given, share the typical range for their scope once (server-written, with an indicative disclaimer) and ask if they''re comfortable going ahead. Replaces the rubric''s ''Don''t quote. Don''t probe.'' Exact prices are still deflected.', false, false),
  ('TYPICAL_BUDGETS', '{"residential_per_sqft_inr":{"low":1800,"high":2400},"per_room_inr":{"low":350000,"high":800000},"commercial_per_sqft_inr":{"low":1200,"high":1800}}'::jsonb, 'Typical (standard-finish) budget bands from pricing.md, used only to build the server-written ''typical budget'' line. Never sent to the agent''s prompt.', false, true),
  ('PRICE_DEFLECTION_LINE_NO_BOOKING', '"Pricing depends on the site, the materials you choose, and the scope — your designer will walk you through it in detail."'::jsonb, 'Price deflection for calls that won''t be booked on the spot (review, callback, messages) — the standard line offers to book, which would mislead those callers.', false, false)
